import{_ as o,C as s,o as n,c as r,j as t,a as d,E as c,a2 as i}from"./chunks/framework.mRCPFc5l.js";const f=JSON.parse('{"title":"React Kit Pages & Routes","description":"Every Inertia page in the React kit with its route, access rules, layout and purpose, from sign-in and settings pages to tenants, users and setup.","frontmatter":{"title":"React Kit Pages & Routes","description":"Every Inertia page in the React kit with its route, access rules, layout and purpose, from sign-in and settings pages to tenants, users and setup.","head":[["link",{"rel":"canonical","href":"https://saas-laravel.com/docs/react/pages.html"}],["meta",{"property":"og:title","content":"React Kit Pages & Routes"}],["meta",{"property":"og:description","content":"Every Inertia page in the React kit with its route, access rules, layout and purpose, from sign-in and settings pages to tenants, users and setup."}],["meta",{"property":"og:url","content":"https://saas-laravel.com/docs/react/pages.html"}],["meta",{"name":"twitter:title","content":"React Kit Pages & Routes"}],["meta",{"name":"twitter:description","content":"Every Inertia page in the React kit with its route, access rules, layout and purpose, from sign-in and settings pages to tenants, users and setup."}]]},"headers":[],"relativePath":"docs/react/pages.md","filePath":"docs/react/pages.md","lastUpdated":1790486087000}'),p={name:"docs/react/pages.md"},l={id:"pages",tabindex:"-1"};function u(h,e,g,m,b,x){const a=s("Badge");return n(),r("div",null,[t("h1",l,[e[0]||(e[0]=d("Pages ",-1)),c(a,{type:"tip",text:"React"}),e[1]||(e[1]=d()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#pages","aria-label":'Permalink to "Pages <Badge type="tip" text="React" />"'},"​",-1))]),e[3]||(e[3]=i('<p>Pages live in <code>resources/js/pages</code>. Each page is a default-exported function component, and its Inertia name is the kebab-case path without <code>.tsx</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Inertia::render(&#39;users/index&#39;) → resources/js/pages/users/index.tsx</span></span></code></pre></div><p>Controllers live in <code>Modules/&lt;Module&gt;/Http/Controllers</code>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Routes marked <strong>central</strong> only exist on the central domain (<code>APP_DOMAIN</code>, <code>central.only</code> middleware). Everything else works on both central and tenant domains, so permissions list both variants (for example <code>View Users|View Tenant Users</code>).</p></div><h2 id="public-and-auth-pages" tabindex="-1">Public and auth pages <a class="header-anchor" href="#public-and-auth-pages" aria-label="Permalink to &quot;Public and auth pages&quot;">​</a></h2><p>Auth pages render inside <code>AuthLayout</code> (card, simple or split). Fortify registers the routes, and <code>Modules/Auth/Providers/AuthServiceProvider.php</code> binds them to these pages.</p><table tabindex="0"><thead><tr><th>Page file</th><th>Route</th><th>Purpose</th></tr></thead><tbody><tr><td><code>home.tsx</code></td><td><code>GET /</code> (<code>home</code>)</td><td>Landing page on the central domain. Tenant domains redirect to <code>login</code>. No layout.</td></tr><tr><td><code>auth/login.tsx</code></td><td><code>GET /login</code> (<code>login</code>)</td><td>Email + password login, passkey login, links to reset/register when enabled for the domain</td></tr><tr><td><code>auth/register.tsx</code></td><td><code>GET /register</code> (<code>register</code>)</td><td>Registration, when enabled for the domain</td></tr><tr><td><code>auth/forgot-password.tsx</code></td><td><code>GET /forgot-password</code> (<code>password.request</code>)</td><td>Request a reset link</td></tr><tr><td><code>auth/reset-password.tsx</code></td><td><code>GET /reset-password/{token}</code> (<code>password.reset</code>)</td><td>Set a new password</td></tr><tr><td><code>auth/verify-email.tsx</code></td><td><code>GET /email/verify</code> (<code>verification.notice</code>)</td><td>Resend the verification email</td></tr><tr><td><code>auth/confirm-password.tsx</code></td><td><code>GET /user/confirm-password</code> (<code>password.confirm</code>)</td><td>Re-enter password before sensitive pages</td></tr><tr><td><code>auth/two-factor-challenge.tsx</code></td><td><code>GET /two-factor-challenge</code> (<code>two-factor.login</code>)</td><td>TOTP code or recovery code; switches the layout title with <code>setLayoutProps</code></td></tr><tr><td><code>auth/accept-invitation.tsx</code></td><td><code>GET /invitation/accept</code> (<code>tenant.invitation.show</code>, tenant, signed) and <code>GET /users/invitation/{user}</code> (<code>users.invitation.show</code>, signed)</td><td>Invited tenant admin or user sets a password. <code>mode</code> prop: <code>&#39;workspace&#39;</code> or <code>&#39;user&#39;</code></td></tr><tr><td><code>auth/maintenance.tsx</code></td><td>Rendered by <code>EnsureTenantIsNotInMaintenance</code> on tenant domains</td><td>Animated maintenance page with the custom message. No layout.</td></tr><tr><td><code>auth/suspended.tsx</code></td><td>Rendered by <code>EnsureTenantIsNotSuspended</code> on tenant domains</td><td>Suspended workspace notice with the custom message. No layout.</td></tr></tbody></table><h2 id="app-pages" tabindex="-1">App pages <a class="header-anchor" href="#app-pages" aria-label="Permalink to &quot;App pages&quot;">​</a></h2><p>App pages render inside <code>AppLayout</code> and require <code>auth</code> + <code>verified</code>.</p><table tabindex="0"><thead><tr><th>Page file</th><th>Route</th><th>Permission</th><th>Purpose</th></tr></thead><tbody><tr><td><code>dashboard.tsx</code></td><td><code>GET /dashboard</code> (<code>dashboard</code>, <code>Route::inertia</code>)</td><td><code>View Analytics Dashboard|View Tenant Dashboard</code></td><td>Dashboard placeholder grid</td></tr><tr><td><code>users/index.tsx</code></td><td><code>GET /users</code> (<code>users.index</code>)</td><td><code>View Users|View Tenant Users</code></td><td>User list with search, stats, pagination, create/edit/delete, invitations, permission assignment</td></tr><tr><td><code>roles/index.tsx</code></td><td><code>GET /roles</code> (<code>roles.index</code>)</td><td><code>View Roles|View Tenant Roles</code></td><td>Role list and create/edit/delete (system roles protected)</td></tr><tr><td><code>tenants/index.tsx</code></td><td><code>GET /tenants</code> (<code>tenants.index</code>) — central</td><td><code>View Tenants</code></td><td>Tenant list with search, status filter and stats</td></tr><tr><td><code>tenants/create.tsx</code></td><td><code>GET /tenants/create</code> (<code>tenants.create</code>) — central</td><td><code>Create Tenant</code></td><td>Create a tenant (company, subdomain, admin, profile data, status)</td></tr><tr><td><code>tenants/show.tsx</code></td><td><code>GET /tenants/{tenant}</code> (<code>tenants.show</code>) — central</td><td><code>View Tenants</code></td><td>Tenant detail: edit, domains, reset admin password, resend invitation, delete</td></tr><tr><td><code>tenants/domains.tsx</code></td><td><code>GET /tenants/domains</code> (<code>tenants.domains</code>) — central</td><td><code>View Tenants</code></td><td>All domains: filters, search, add, set primary, delete, per-domain settings and auth features</td></tr></tbody></table><h2 id="settings-pages" tabindex="-1">Settings pages <a class="header-anchor" href="#settings-pages" aria-label="Permalink to &quot;Settings pages&quot;">​</a></h2><p><code>settings/*</code> pages render inside <code>AppLayout</code> plus the settings sub-navigation (<code>layouts/settings/layout.tsx</code>). <code>GET /settings</code> redirects to <code>/settings/profile</code>.</p><table tabindex="0"><thead><tr><th>Page file</th><th>Route</th><th>Purpose</th></tr></thead><tbody><tr><td><code>settings/profile.tsx</code></td><td><code>GET /settings/profile</code> (<code>profile.edit</code>)</td><td>Name, email, language (&quot;Default&quot; follows the domain), email verification notice, delete account</td></tr><tr><td><code>settings/security.tsx</code></td><td><code>GET /settings/security</code> (<code>security.edit</code>), requires password confirmation</td><td>Change password, two-factor authentication, passkeys</td></tr><tr><td><code>settings/appearance.tsx</code></td><td><code>GET /settings/appearance</code> (<code>appearance.edit</code>, <code>Route::inertia</code>)</td><td>Light / dark / system</td></tr><tr><td><code>settings/layout.tsx</code></td><td><code>GET /settings/layout</code> (<code>layout.edit</code>)</td><td>Personal layout: app layout, sidebar variant, collapsible mode</td></tr></tbody></table><h2 id="setup-pages" tabindex="-1">Setup pages <a class="header-anchor" href="#setup-pages" aria-label="Permalink to &quot;Setup pages&quot;">​</a></h2><p><code>setup/*</code> pages use the plain <code>AppLayout</code>. While the URL starts with <code>/setup</code>, the sidebar shows <code>setupMenus</code> instead of the main menu. <code>GET /setup</code> redirects to <code>/setup/menus</code>.</p><table tabindex="0"><thead><tr><th>Page file</th><th>Route</th><th>Permission</th><th>Purpose</th></tr></thead><tbody><tr><td><code>setup/menus.tsx</code></td><td><code>GET /setup/menus</code> (<code>setup.menus.index</code>)</td><td><code>View Navigation Menus|View Tenant Menus</code></td><td>Drag &amp; drop menu order (<code>sortablejs</code>), reset to defaults</td></tr><tr><td><code>setup/layout.tsx</code></td><td><code>GET /setup/layout</code> (<code>setup.layout.index</code>)</td><td><code>Update Layout Settings|Update Tenant Layout</code></td><td>Global default app layout, sidebar settings and auth layout</td></tr><tr><td><code>setup/tenant-settings.tsx</code></td><td><code>GET /setup/tenant-settings</code> (<code>setup.tenant-settings.edit</code>) — central</td><td><code>Manage Tenant Maintenance</code></td><td>Global maintenance mode for tenant workspaces</td></tr></tbody></table><h2 id="error-page" tabindex="-1">Error page <a class="header-anchor" href="#error-page" aria-label="Permalink to &quot;Error page&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page file</th><th>Rendered by</th><th>Purpose</th></tr></thead><tbody><tr><td><code>errors/error.tsx</code></td><td>Exception handler in <code>bootstrap/app.php</code></td><td>403, 404, 500 and 503 responses. Uses <code>AppLayout</code> for signed-in users and <code>AuthLayout</code> for guests.</td></tr></tbody></table><p>In <code>local</code> and <code>testing</code>, only 403 renders this page. Other statuses show Laravel&#39;s debug page.</p><h2 id="partials" tabindex="-1">Partials <a class="header-anchor" href="#partials" aria-label="Permalink to &quot;Partials&quot;">​</a></h2><p>Page-specific modals and sections live in <code>partials/</code> next to the page:</p><table tabindex="0"><thead><tr><th>File</th><th>Used by</th></tr></thead><tbody><tr><td><code>users/partials/user-form-modal.tsx</code></td><td>Create/edit user, &quot;Send invitation email&quot;</td></tr><tr><td><code>users/partials/assign-user-permissions-modal.tsx</code></td><td>Grouped permission checkboxes for one user</td></tr><tr><td><code>roles/partials/role-form-modal.tsx</code></td><td>Create/edit role</td></tr><tr><td><code>tenants/partials/edit-tenant-modal.tsx</code></td><td>Edit tenant details and status</td></tr><tr><td><code>tenants/partials/organization-domains.tsx</code></td><td>Domains card on the tenant detail page</td></tr><tr><td><code>tenants/partials/domain-modal.tsx</code></td><td>Add a domain</td></tr><tr><td><code>tenants/partials/domain-settings-modal.tsx</code></td><td>Per-domain App name and default language</td></tr><tr><td><code>tenants/partials/domain-auth-features-modal.tsx</code></td><td>Per-domain registration / password reset / verification / 2FA / passkeys toggles</td></tr><tr><td><code>tenants/partials/reset-password-modal.tsx</code></td><td>Send a reset link or set the tenant admin password</td></tr><tr><td><code>tenants/partials/maintenance-mode-form.tsx</code></td><td>Maintenance message, secret bypass link, allowed IPs</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Adding a page? Follow <a href="/docs/react/development.html#adding-a-page">Development → Adding a page</a>.</p></div>',23))])}const w=o(p,[["render",u]]);export{f as __pageData,w as default};
